using MagicAssistant.App.Shared;
using MagicAssistant.Data.Model;

namespace MagicAssistant.Tests.ColorFilter;

/// <summary>
/// Round-trip tests: verify that ColorBits computed by ColorBitBuilder actually pass through
/// the SQL WHERE clause generated by ColorFilter.ToSqlWhere().
/// 
/// This catches bugs where filter logic is internally consistent but incompatible with real data.
/// E.g., optimization "ColorBits = 2" fails because real cards have ColorBits = 6 (W|MONO).
/// </summary>
[TestFixture]
public class ColorFilterRoundTripTests
{
    /// <summary>
    /// Evaluates a ColorFilter directly against card ColorBits using C# bitwise logic.
    /// This mirrors what SqliteCardStore.GetPagedAsync does with the generated SQL WHERE fragment,
    /// but avoids fragile SQL string parsing (especially for nested MULTI/MONO conditions).
    /// </summary>
    private static bool PassesFilter(int colorBits, MagicAssistant.Data.Model.ColorFilter filter)
    {
        // Required colors: AND or OR
        if (filter.AndMode)
        {
            if ((colorBits & filter.RequiredMask) != filter.RequiredMask)
                return false;
        }
        else
        {
            if ((colorBits & filter.RequiredMask) != 0)
            { /* passes */ }
            else if (filter.RequiredMask != 0)
                return false;
        }

        // Excluded colors: must not be present
        if (filter.ExcludedMask > 0)
        {
            if ((colorBits & filter.ExcludedMask) != 0)
                return false;
        }

        const int ColoredMask = 0x03E; // W|U|B|R|G
        var coloredBits = colorBits & ColoredMask;

        // Multi-color: at least 2 colored bits set (not power of two)
        if (filter.RequiresMultiColor)
        {
            if (coloredBits == 0) return false;
            if ((coloredBits & (coloredBits - 1)) == 0) return false; // power of two = only 1 bit
        }

        // Mono-color: exactly 1 colored bit set (power of two)
        if (filter.RequiresMonoColor)
        {
            if (coloredBits == 0) return false;
            if ((coloredBits & (coloredBits - 1)) != 0) return false; // not power of two
        }

        return true;
    }

    private Dictionary<ColorBitFlags, bool> EmptyBoxes()
    {
        var boxes = new Dictionary<ColorBitFlags, bool>();
        foreach (var flag in ColorFilterFlags.All)
            boxes[flag] = false;
        return boxes;
    }

    private void Set(Dictionary<ColorBitFlags, bool> boxes, ColorBitFlags flag)
        => boxes[flag] = true;

    // ── Round-trip: card bits → filter → SQL → card passes ──

    [Test]
    public void RoundTrip_MonoWhite_CardsPassWhenWhiteSelected()
    {
        // Card: {W} → ColorBits = W(0x002) | MONO(0x080) = 130
        var cardBits = ColorBitBuilder.Build(["W"], "{W}");
        Assert.That(cardBits, Is.EqualTo(0x082), "Setup: mono-white should have W|MONO bits (0x002 | 0x080)");

        // Filter: White selected (OR mode)
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(PassesFilter(cardBits, filter), Is.True,
            "Mono-white card must pass when White is selected");
    }

    [Test]
    public void RoundTrip_MonoWhite_CardsFailWhenBlueSelected()
    {
        var cardBits = ColorBitBuilder.Build(["W"], "{W}");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.U); // Blue only
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(PassesFilter(cardBits, filter), Is.False,
            "Mono-white card must NOT pass when only Blue is selected");
    }

    [Test]
    public void RoundTrip_MultiColor_PassWhenBothColorsSelected()
    {
        // Card: {W}{U} → ColorBits = W|U|MULTI = 70
        var cardBits = ColorBitBuilder.Build(["W", "U"], "{W}{U}");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(PassesFilter(cardBits, filter), Is.True,
            "Multi-color card must pass when both colors selected (OR mode)");
    }

    [Test]
    public void RoundTrip_MultiColor_PassWhenAndModeBothSelected()
    {
        var cardBits = ColorBitBuilder.Build(["W", "U"], "{W}{U}");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        var filter = ColorFilterHelper.GetFilter(boxes, andMode: true)!;

        Assert.That(PassesFilter(cardBits, filter), Is.True,
            "Multi-color card must pass AND mode (both W and U present)");
    }

    [Test]
    public void RoundTrip_MonoWhite_FailsAndModeWithTwoColors()
    {
        // Card: {W} → only W, no U
        var cardBits = ColorBitBuilder.Build(["W"], "{W}");

        // Filter: W AND U required
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        var filter = ColorFilterHelper.GetFilter(boxes, andMode: true)!;

        Assert.That(PassesFilter(cardBits, filter), Is.False,
            "Mono-white card must fail AND mode (U not present)");
    }

    [Test]
    public void RoundTrip_OnlyMode_ExcludesOtherBaseColors()
    {
        // Card: {W}{U} → W|U|MULTI = 70
        var cardBits = ColorBitBuilder.Build(["W", "U"], "{W}{U}");

        // Filter: White only (excludes U,B,R,G,C but NOT MULTI)
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        var filter = ColorFilterHelper.GetFilter(boxes, onlyMode: true)!;

        Assert.That(PassesFilter(cardBits, filter), Is.False,
            "WU card must fail when only White selected (U is excluded)");
    }

    [Test]
    public void RoundTrip_OnlyMode_AllowsComputedBits()
    {
        // Card: {W} → W|MONO = 6
        var cardBits = ColorBitBuilder.Build(["W"], "{W}");

        // Filter: White only
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        var filter = ColorFilterHelper.GetFilter(boxes, onlyMode: true)!;

        Assert.That(PassesFilter(cardBits, filter), Is.True,
            "Mono-white card must pass White-only filter (MONO bit is not excluded)");
    }

    [Test]
    public void RoundTrip_Colorless_PassWhenColorlessSelected()
    {
        // Card: land → C = 1
        var cardBits = ColorBitBuilder.Build(Array.Empty<string>(), "");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.C);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(PassesFilter(cardBits, filter), Is.True);
    }

    [Test]
    public void RoundTrip_Colorless_FailsWhenWhiteSelected()
    {
        var cardBits = ColorBitBuilder.Build(Array.Empty<string>(), "");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(PassesFilter(cardBits, filter), Is.False);
    }

    [Test]
    public void RoundTrip_HybridCard_PassWhenHybridAndColorSelected()
    {
        // Card: {W/U} → W|U|HYBRID = 2+4+256 = 262 (HYBRID replaces MULTI, mutually exclusive)
        var cardBits = ColorBitBuilder.Build(["W", "U"], "{W/U}");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.HYBRID);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(PassesFilter(cardBits, filter), Is.True,
            "Hybrid card must pass when both color and HYBRID selected");
    }

    [Test]
    public void RoundTrip_IdentityMode_ChecksIdentityBits()
    {
        // Card with only W in identity (mono-white identity)
        var identityBits = ColorBitBuilder.Build(null, "{W}", ["W"]);
        
        // Filter: White only, identity mode
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        var filter = ColorFilterHelper.GetFilter(boxes, identityMode: true)!;

        // IdentityBits has W|MONO (0x082) → should pass W filter
        Assert.That(PassesFilter(identityBits, filter), Is.True,
            "Card with W-only identity must pass White identity filter");
    }

    [Test]
    public void RoundTrip_NoFilter_PassAllCards()
    {
        var whiteCard = ColorBitBuilder.Build(["W"], "{W}");
        var multiCard = ColorBitBuilder.Build(["W", "U"], "{W}{U}");
        var colorlessCard = ColorBitBuilder.Build(Array.Empty<string>(), "");

        var filter = new MagicAssistant.Data.Model.ColorFilter();

        Assert.That(filter.ToSqlWhere(), Is.Null);
        Assert.That(PassesFilter(whiteCard, filter), Is.True);
        Assert.That(PassesFilter(multiCard, filter), Is.True);
        Assert.That(PassesFilter(colorlessCard, filter), Is.True);
    }

    // ── Bug regression: MULTI checkbox must actually filter multi-color cards ──

    [Test]
    public void Regression_MultiCheckbox_ExcludesMonoCards()
    {
        // Flare of Denial: {1}{U}{U} → mono-blue, ColorBits = U|MONO = 0x084
        var monoBlueCard = ColorBitBuilder.Build(["U"], "{1}{U}{U}");
        Assert.That(monoBlueCard, Is.EqualTo(0x084), "Setup: mono-blue should be U|MONO");

        // Filter: W + U + MULTI + Only (the exact bug scenario)
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        Set(boxes, ColorBitFlags.MULTI);
        var filter = ColorFilterHelper.GetFilter(boxes, onlyMode: true)!;

        Assert.That(filter.RequiresMultiColor, Is.True, "MULTI checkbox must set RequiresMultiColor");
        Assert.That(PassesFilter(monoBlueCard, filter), Is.False,
            "Mono-blue card must NOT pass W+U+MULTI+Only filter (it's not multi-color)");
    }

    [Test]
    public void Regression_MultiCheckbox_AllowsActualMultiColorCards()
    {
        // WU card: {W}{U} → ColorBits = W|U|MULTI = 0x046
        var wuCard = ColorBitBuilder.Build(["W", "U"], "{W}{U}");

        // Filter: W + U + MULTI + Only
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        Set(boxes, ColorBitFlags.MULTI);
        var filter = ColorFilterHelper.GetFilter(boxes, onlyMode: true)!;

        Assert.That(PassesFilter(wuCard, filter), Is.True,
            "WU multi-color card must pass W+U+MULTI+Only filter");
    }

    [Test]
    public void Regression_MonoCheckbox_ExcludesMultiColorCards()
    {
        // WU card: {W}{U} → ColorBits = W|U|MULTI = 0x046
        var wuCard = ColorBitBuilder.Build(["W", "U"], "{W}{U}");

        // Filter: MONO only
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.MONO);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(filter.RequiresMonoColor, Is.True);
        Assert.That(PassesFilter(wuCard, filter), Is.False,
            "Multi-color card must NOT pass MONO-only filter");
    }

    [Test]
    public void Regression_MultiOnly_NoBaseColors()
    {
        // Only MULTI checkbox, no base colors — should return any multi-color card
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.MULTI);
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Assert.That(filter.RequiredMask, Is.Zero, "No base colors → RequiredMask = 0");
        Assert.That(filter.RequiresMultiColor, Is.True);

        // Mono-blue card should fail
        var monoBlue = ColorBitBuilder.Build(["U"], "{U}");
        Assert.That(PassesFilter(monoBlue, filter), Is.False);

        // WU multi-color card should pass
        var wuCard = ColorBitBuilder.Build(["W", "U"], "{W}{U}");
        Assert.That(PassesFilter(wuCard, filter), Is.True);
    }

    // ── Exact reproduction: Aether Spike / Flare of Denial under W+U+MULTI+Only ──

    [Test]
    public void Regression_AetherSpike_W_U_Multi_Only_Excluded()
    {
        // Aether Spike: {1}{U}, MONO-U, ColorBits = U|MONO = 0x084
        var cardBits = ColorBitBuilder.Build(["U"], "{1}{U}");
        Assert.That(cardBits, Is.EqualTo(0x084), $"Setup: expected 0x084, got 0x{cardBits:X}");

        // Filter: W + U + MULTI + Only
        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        Set(boxes, ColorBitFlags.MULTI);
        var filter = ColorFilterHelper.GetFilter(boxes, onlyMode: true)!;

        // Debug: print filter state
        Console.WriteLine($"Filter: {filter}");
        Console.WriteLine($"SQL: {filter.ToSqlWhere()}");
        Console.WriteLine($"Card ColorBits: 0x{cardBits:X}");
        Console.WriteLine($"Passes C# filter: {PassesFilter(cardBits, filter)}");

        Assert.That(filter.RequiresMultiColor, Is.True, "MULTI must set RequiresMultiColor");
        Assert.That(filter.RequiredMask, Is.EqualTo(0x006), $"RequiredMask should be W|U=0x006, got 0x{filter.RequiredMask:X}");
        Assert.That(PassesFilter(cardBits, filter), Is.False,
            "Aether Spike (mono-blue) must NOT pass W+U+MULTI+Only — it's not multi-color");
    }

    [Test]
    public void Regression_FlareOfDenial_W_U_Multi_Only_Excluded()
    {
        // Flare of Denial: {1}{U}{U}, MONO-U, ColorBits = U|MONO = 0x084
        var cardBits = ColorBitBuilder.Build(["U"], "{1}{U}{U}");
        Assert.That(cardBits, Is.EqualTo(0x084), $"Setup: expected 0x084, got 0x{cardBits:X}");

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        Set(boxes, ColorBitFlags.MULTI);
        var filter = ColorFilterHelper.GetFilter(boxes, onlyMode: true)!;

        Assert.That(PassesFilter(cardBits, filter), Is.False,
            "Flare of Denial (mono-blue) must NOT pass W+U+MULTI+Only");
    }

    [Test]
    public void Regression_AetherSpike_W_U_Multi_NoOnly_Excluded()
    {
        // Same card, same MULTI checkbox — WITHOUT Only mode.
        // This is the MORE LIKELY scenario: user checks W+U+MULTI and forgets Only.
        var cardBits = ColorBitBuilder.Build(["U"], "{1}{U}");
        Assert.That(cardBits, Is.EqualTo(0x084));

        var boxes = EmptyBoxes();
        Set(boxes, ColorBitFlags.W);
        Set(boxes, ColorBitFlags.U);
        Set(boxes, ColorBitFlags.MULTI);
        // onlyMode: false — user didn't check Only
        var filter = ColorFilterHelper.GetFilter(boxes)!;

        Console.WriteLine($"Filter (no Only): {filter}");
        Console.WriteLine($"SQL: {filter.ToSqlWhere()}");

        Assert.That(filter.RequiresMultiColor, Is.True);
        Assert.That(filter.ExcludedMask, Is.Zero, "No Only → no exclusions");
        Assert.That(PassesFilter(cardBits, filter), Is.False,
            "Aether Spike (mono-blue) must NOT pass W+U+MULTI even without Only — MULTI requires 2+ colors");
    }
}
